statement:
`isWater` is an `m x n` grid where `1` marks a water cell and `0` marks a land cell. Give every cell an integer height so that:

- no height is negative;
- every water cell has height `0`;
- two cells that share a side (up, down, left or right) differ in height by at most `1`.

Among all such assignments, choose one whose largest height is as large as possible, and return it as an `m x n` matrix `height`, where `height[i][j]` belongs to cell `(i, j)`. When several assignments reach that largest height, any one of them is accepted. The grid always contains at least one water cell.

checker:
function check(input, actual, expected) {
  const grid = input[0];
  const m = grid.length;
  const n = grid[0].length;
  if (!Array.isArray(actual) || actual.length !== m) return false;
  let target = 0;
  for (const row of expected) for (const v of row) target = Math.max(target, v);
  let best = 0;
  for (let i = 0; i < m; i++) {
    if (!Array.isArray(actual[i]) || actual[i].length !== n) return false;
    for (let j = 0; j < n; j++) {
      const h = actual[i][j];
      if (!Number.isInteger(h) || h < 0) return false;
      if (grid[i][j] === 1 && h !== 0) return false;
      if (i > 0 && Math.abs(h - actual[i - 1][j]) > 1) return false;
      if (j > 0 && Math.abs(h - actual[i][j - 1]) > 1) return false;
      best = Math.max(best, h);
    }
  }
  return best === target;
}

validator:
function validate([isWater]) {
  if (!Array.isArray(isWater) || isWater.length < 1 || isWater.length > 1000) return 'isWater needs 1 to 1000 rows.';
  const n = isWater[0].length;
  if (n < 1 || n > 1000) return 'Each row needs 1 to 1000 cells.';
  let water = false;
  for (const row of isWater) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    for (const v of row) {
      if (v !== 0 && v !== 1) return 'Each cell is 0 (land) or 1 (water).';
      if (v === 1) water = true;
    }
  }
  if (!water) return 'The grid needs at least one water cell.';
  return null;
}

