function highestPeak(isWater) {
  // With no obstacles, the best height of a cell is its Manhattan distance to the nearest water cell.
  const water = [];
  isWater.forEach((row, i) => row.forEach((v, j) => { if (v === 1) water.push([i, j]); }));
  return isWater.map((row, i) => row.map((_, j) => Math.min(...water.map(([wi, wj]) => Math.abs(wi - i) + Math.abs(wj - j)))));
}

