function generate(rand, size) {
  const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const sparse = rand() < 0.5;
  const density = sparse ? 0 : (size === 'large' ? 0.002 + rand() * 0.05 : 0.1 + rand() * 0.5);
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  // Sparse grids get only one to three water cells; every grid needs at least one.
  const extra = sparse ? 1 + Math.floor(rand() * 3) : 1;
  if (sparse || !grid.some(row => row.includes(1))) {
    for (let k = 0; k < extra; k++) grid[Math.floor(rand() * m)][Math.floor(rand() * n)] = 1;
  }
  return [grid];
}
